import{_ as i,C as t,o as l,c as d,j as s,a as h,E as a,a6 as o}from"./chunks/framework.CCKCzdWs.js";const c="/screenshots/run-timeline-leaks.png",p="/screenshots/run-resources.png",x=JSON.parse('{"title":"Resource leaks","description":"The browsers, contexts, pages and API request contexts your tests leave open or open for nothing, listed at the end of each run and on its Resources tab, with the line that opened them.","frontmatter":{"title":"Resource leaks","description":"The browsers, contexts, pages and API request contexts your tests leave open or open for nothing, listed at the end of each run and on its Resources tab, with the line that opened them.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/resource-leaks.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/resource-leaks.html"}],["meta",{"property":"og:title","content":"Resource leaks | Piwi for Playwright"}],["meta",{"property":"og:description","content":"The browsers, contexts, pages and API request contexts your tests leave open or open for nothing, listed at the end of each run and on its Resources tab, with the line that opened them."}]]},"headers":[],"relativePath":"features/resource-leaks.md","filePath":"features/resource-leaks.md","lastUpdated":1794647275000}'),u={name:"features/resource-leaks.md"};function f(g,e,m,w,k,b){const r=t("Needs"),n=t("DemoExamples");return l(),d("div",null,[e[0]||(e[0]=s("h1",{id:"resource-leaks",tabindex:"-1"},[h("Resource leaks "),s("a",{class:"header-anchor",href:"#resource-leaks","aria-label":'Permalink to "Resource leaks"'},"​")],-1)),a(r,{reporter:"",fixtures:""}),e[1]||(e[1]=o(`<p>A browser context a test never closes keeps its renderer processes, memory and CPU until the worker shuts down, and every later test on that worker runs next to it. Playwright closes what its own fixtures open; what a test opens by hand is the test&#39;s to close. The <a href="/guide/capture-fixtures.html">capture fixtures</a> keep a ledger of what each test opens, and at the end of the run the reporter lists what stayed open past the scope that opened it, with its line.</p><h2 id="the-summary" tabindex="-1">The summary <a class="header-anchor" href="#the-summary" aria-label="Permalink to &quot;The summary&quot;">​</a></h2><p>The reporter prints it after the last test, before the upload, and adds it to the job summary on GitHub Actions:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Piwi Dashboard] Resources: 3 leaks · 6 idle pages · 1 piling up · 1 handle left in workers · 1 lingering</span></span>
<span class="line"><span>[Piwi Dashboard]   leaked    context     tests/cart.spec.ts:12 · 4 contexts · with 4 pages · 4 tests · open until the worker shut down (41.2 s past its test) · 18.3 s of page CPU after its test · last used at tests/cart.spec.ts:15</span></span>
<span class="line"><span>[Piwi Dashboard]   leaked    page        popup after locator.click at tests/checkout.spec.ts:30 · 2 pages · 2 tests · open 3.1 s past its test · last used at tests/checkout.spec.ts:31</span></span>
<span class="line"><span>[Piwi Dashboard]   leaked    context     tests/admin.spec.ts:8 · beforeAll of &quot;admin&quot; · 1 test · open until the worker shut down (12.0 s past its describe block) · last used at tests/admin.spec.ts:19</span></span>
<span class="line"><span>[Piwi Dashboard]   piling    listeners   fixture &quot;adminPage&quot; at tests/fixtures.ts:21 · 11 → 31 listeners over 20 tests</span></span>
<span class="line"><span>[Piwi Dashboard]   handle    server      tests/pay.spec.ts:14 · left running in the worker by &quot;mocks the payment API&quot; (tests/pay.spec.ts)</span></span>
<span class="line"><span>[Piwi Dashboard]   idle      page        fixture &quot;page&quot; · 6 pages · 6 tests · set up with consoleCollector (tests/fixtures.ts:40)</span></span>
<span class="line"><span>[Piwi Dashboard]   lingering page        popup after locator.click at tests/export.spec.ts:22 · 1 test · open 6.4 s after its last use · last used at tests/export.spec.ts:23</span></span>
<span class="line"><span>[Piwi Dashboard] Set leakCheck: &#39;fail&#39; (PIWI_LEAK_CHECK=fail) to fail the tests that leave what they open, or &#39;close&#39; to close it.</span></span></code></pre></div><p>Findings of one line are grouped: the first above is one line leaking in four tests. Each leak names the line that last used it, where its <code>close()</code> belongs. A leaked context or browser carries the pages open in it, and a page <code>browser.newPage()</code> opened carries the context made for it. At most ten findings are listed; the rest are counted. In Chromium, the fixtures read each page that outlives its test over the DevTools protocol, so a leak also says how much CPU its pages&#39; main threads used after their test, from half a second. The <a href="./cpu-memory-disk.html">CPU, memory &amp; disk</a> panel follows, with what the whole run cost the machine.</p><h2 id="what-it-reports" tabindex="-1">What it reports <a class="header-anchor" href="#what-it-reports" aria-label="Permalink to &quot;What it reports&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Finding</th><th>What it means</th><th>The usual fix</th></tr></thead><tbody><tr><td><strong>leaked</strong>, past its test</td><td>Opened by the test body or its <code>beforeEach</code>/<code>afterEach</code>, and still open when the test ended. Nothing in the same file closed it later.</td><td><code>close()</code> or <code>dispose()</code> before the test ends, or <code>await using</code></td></tr><tr><td><strong>leaked</strong>, past its describe block</td><td>Opened in a <code>beforeAll</code> (or an <code>afterAll</code>) and still open once the tests of its describe block ran.</td><td>Close it in <code>afterAll</code></td></tr><tr><td><strong>piling up</strong></td><td>A page or context living across tests whose open pages, listeners, route handlers or DOM elements kept growing; or a worker whose open file descriptors, or heap after V8&#39;s own full garbage collections, did</td><td>Remove what each test adds or opens; in a worker, what a module variable, cache or pool keeps</td></tr><tr><td><strong>handle</strong></td><td>A server, child process or file watcher a test started and left running in the worker; a server or process at its line</td><td>Close or kill it in the test or an <code>afterEach</code></td></tr><tr><td><strong>idle</strong></td><td>A page opened and never used: no navigation, and no call of the test&#39;s on it. The detail names the fixtures of yours that set it up.</td><td>Drop the <code>page</code> argument, or the fixture that asks for it</td></tr><tr><td><strong>lingering</strong></td><td>A browser, context or page the test body opened and closed within the test, but long after its last use: at least 2 s, and a third of the test or more. A popup checked once, then left to the <code>page</code> fixture. What a hook or a fixture opens, and an API request context, never is.</td><td>Close it right after its last use</td></tr><tr><td><strong>probable</strong></td><td>Without the fixtures, from a test&#39;s steps: a browser, context or <code>browser.newPage()</code> page nothing in its file closed</td><td>Use the fixtures for exact findings</td></tr></tbody></table><p>What is never reported:</p><ul><li>what a <strong>worker-scoped fixture</strong> holds, servers and processes included: it lives as long as the worker;</li><li>a context Playwright <strong>reuses</strong> on purpose (UI mode, <code>--reuse-context</code>);</li><li>an object <strong>handed on</strong> to a later test, or a <code>beforeAll</code> object an <code>afterAll</code> closes, within the same file;</li><li>what a <strong>failed test</strong> left open: Playwright shuts its worker down right after it.</li></ul><h2 id="fail-or-close-leaks" tabindex="-1">Fail or close leaks <a class="header-anchor" href="#fail-or-close-leaks" aria-label="Permalink to &quot;Fail or close leaks&quot;">​</a></h2><p><code>leakCheck</code> (or <code>PIWI_LEAK_CHECK</code>) decides what the fixtures do with an object a test opened itself and left open:</p><ul><li><code>&#39;report&#39;</code>, the default, only lists it;</li><li><code>&#39;fail&#39;</code> also fails the test, naming each object and its line;</li><li><code>&#39;close&#39;</code> closes it when the test ends, and lists it as <em>closed by Piwi</em>.</li></ul><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wrapConfig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(config, { projectName: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;my-project&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, leakCheck: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;fail&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error: Piwi: this test left one object open:</span></span>
<span class="line"><span>  - a context opened at tests/cart.spec.ts:12, with 1 page, last used at tests/cart.spec.ts:15</span></span>
<span class="line"><span>Close each after its last use (await using, close() or dispose()), or set PIWI_LEAK_CHECK=report to only list them.</span></span></code></pre></div><p>A <code>beforeAll</code> object, and what a fixture opens, are only ever reported. Each test is judged when it ends, so a test that hands what it opened to the next one fails under <code>&#39;fail&#39;</code> and loses it under <code>&#39;close&#39;</code>: open such objects in <code>beforeAll</code> and close them in <code>afterAll</code>.</p><p>The ledger is on whenever the fixtures are. Turn it off with <code>captureResources: false</code> (or <code>PIWI_CAPTURE_RESOURCES=false</code>). Like every fixture option, set both through <a href="/guide/reporter.html#installing-via-wrapconfig"><code>wrapConfig</code></a> or their variable: the test workers never see a plain reporter entry&#39;s options.</p><h2 id="in-the-dashboard" tabindex="-1">In the dashboard <a class="header-anchor" href="#in-the-dashboard" aria-label="Permalink to &quot;In the dashboard&quot;">​</a></h2><p>A run whose reporter sent findings shows a <strong>Resources</strong> tab:</p><ul><li>the counts of each kind of finding, the CPU the run&#39;s processes used and the machine&#39;s peak memory;</li><li>the findings, each with the line or fixture that opened it and the line that last used it, one click from your editor;</li><li>a switch drawing each worker&#39;s open pages on the run&#39;s <a href="./cpu-memory-disk.html#in-the-dashboard">Timeline tab</a>: a leak climbs test after test, a clean worker stays flat;</li><li>the machine each shard ran on, from the <a href="./cpu-memory-disk.html#in-the-dashboard">CPU, memory &amp; disk</a> panel;</li><li>the <strong>costliest tests</strong>, by the CPU of their worker and browser processes, with the pages each found already open.</li></ul><p>On the run&#39;s <strong>Timeline</strong> tab, a red tail under a worker&#39;s row runs from the test that left an object open to its close or the worker&#39;s end, and an amber one from an object&#39;s last use to its close. Hover one for its lines; click it to open its test. The open pages graphs draw the pages left open in red, and <strong>Show leaks</strong> turns all of it off.</p><figure><img src="`+c+'" alt="A run&#39;s Timeline tab: under each worker&#39;s row, red tails from each test&#39;s end to the worker&#39;s end, one amber tail inside a test, and the tooltip of the amber one naming where the popup was opened, its test, how long it stayed open after its last use and the line that last used it"><figcaption>Leaks under each worker on the Timeline tab.</figcaption></figure><p>The execution page&#39;s Performance tab shows what that one test cost and what it left open. A project that declines the <strong>Resources</strong> capability in <strong>Settings → Capabilities</strong> hides both, and the reporter&#39;s summary stays as it is.</p><figure><img src="'+p+'" alt="A run&#39;s Resources tab: counts of leaked, never-used, piling-up and left-running resources, the four findings, each with the fixture, file or test behind it, the machine&#39;s CPU, memory and disk, and the costliest tests"><figcaption>A run&#39;s Resources tab.</figcaption></figure><h2 id="in-ci" tabindex="-1">In CI <a class="header-anchor" href="#in-ci" aria-label="Permalink to &quot;In CI&quot;">​</a></h2><p>Each finding keeps a history across runs: whether it is new to a pull request&#39;s base branch, and once fixed, the run that fixed it. <code>piwi gate</code>, the pull-request comment and MCP read it: <a href="./leak-history.html">Leak history in CI</a>.</p><h2 id="cost" tabindex="-1">Cost <a class="header-anchor" href="#cost" aria-label="Permalink to &quot;Cost&quot;">​</a></h2><p>The ledger listens to the calls Playwright already reports and does its bookkeeping at the end of each test, adding nothing to the steps or the trace. In Chromium, a page still open at the end of a test is read over the DevTools protocol: about 20 ms the first time, to open a session, then a couple of milliseconds per test while it stays open. Servers and child processes are placed by wrapping Node&#39;s <code>listen</code> and <code>spawn</code> in each worker.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>The dashboard keeps the first 100 findings of each run, most severe first.</li><li><strong>Playwright internals.</strong> The ledger reads Playwright&#39;s instrumentation hooks, the calls on the worker&#39;s connection to its browsers, the runner&#39;s current test and fixture, and a few private fields (<code>_routes</code>, <code>_ownerPage</code>, <code>_opener</code>). Each is checked before use: without the hooks the ledger stays off, and without the connection a page counts as used only when it navigates, loads, runs a script or builds a locator, and no finding names a last use.</li><li>An object kept in a module variable on purpose and closed by another spec file reads as leaked.</li><li>A fixture with a <code>timeout</code> of its own runs with the slot a worker fixture has: what it leaves open is reported once its test&#39;s teardown steps show it torn down with the test, or once it opened something in two tests of the same worker. A boxed one (<code>box: true</code>) leaves no step, so only the second applies.</li><li><strong>Probable leaks</strong> come from step titles, which name no object, and the lines they point at. A close goes to the open assigned its name (<code>ctx</code> in <code>ctx.close()</code>); <code>page.context().close()</code>, on no name, may take another object of its test. A page counts as <code>browser.newPage()</code> when the name before <code>.newPage</code> is a browser&#39;s. A browser&#39;s <code>close()</code> closes what was opened on its name. A fixture&#39;s objects and API request contexts, whose <code>dispose()</code> leaves no step, are never counted.</li><li>Sockets and timers are not reported: they move on every test, Playwright&#39;s own included. DOM elements are counted in Chromium only, and a small heap leak shows only over a long run.</li></ul><h2 id="try-it-in-the-demo" tabindex="-1">Try it in the demo <a class="header-anchor" href="#try-it-in-the-demo" aria-label="Permalink to &quot;Try it in the demo&quot;">​</a></h2><p>The <a href="https://piwitests.dev/demo/" target="_blank" rel="noreferrer">live demo</a> holds a leaky run, and its run simulator replays one: pick <strong>Leaky run</strong>.</p>',31)),a(n),e[2]||(e[2]=o('<h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/guide/capture-fixtures.html">Capture fixtures</a>: what else the fixtures record</li><li><a href="/reference/reporter-options.html#what-gets-captured">Reporter options</a>: <code>captureResources</code> and <code>leakCheck</code></li><li><a href="./leak-history.html">Leak history in CI</a>: new leaks, fixed ones, and the gate</li><li><a href="./cpu-memory-disk.html">CPU, memory &amp; disk</a>: what the whole run cost the machine</li><li><a href="./slow-tests.html">Slow tests &amp; wasted time</a>: where the suite&#39;s time goes</li></ul>',2))])}const v=i(u,[["render",f]]);export{x as __pageData,v as default};
